  if (error) return <main><p>The article could not be loaded ({error}).</p></main>
  if (!article) return <main><p>Loading the article…</p></main>
  return (
    <main
      style={{
        display: 'grid',
        gridTemplateColumns: 'repeat(auto-fit, minmax(18rem, 1fr))',
        gap: '2rem',
        padding: '1rem',
