"""The headline as the site shows it: the OCR's headline without the masthead lines that an
article's first box often takes in. The stored OCR keeps them."""

import html
import re

# a weekday, month or time of day, as a masthead's dateline prints them
DATE_WORDS = re.compile(
    r"\b(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday|morning|evening"
    r"|january|february|march|april|may|june|july|august|september|october|november"
    r"|december|jan|feb|mar|apr|jun|jul|aug|sept?|oct|nov|dec)\b",
    re.IGNORECASE,
)
ISSUE_WORDS = re.compile(
    r"\b(?:new|series|vol|volume|no|number|whole|page)\b", re.IGNORECASE
)
# numbers as printed and as OCR misreads them (I or l for 1, O for 0), and roman numerals
NUMERALS = re.compile(r"\b(?:[\dIilOo]+|[IVXLCDM]+)\b")


def letters(text):
    return re.sub(r"[^a-z]", "", text.lower())


def spelled(word):
    """These letters with anything but letters between them, since OCR splits a
    masthead's wide lettering: 'portland' matches 'PORTL AND'."""
    return r"[\W\d_]*".join(map(re.escape, word))


def names(paper):
    """The paper's title, with or without 'The', and its place, from the LoC title: 'The
    national era. [volume] (Washington [D.C.]) 1847-1860' gives national era and
    Washington."""
    paper = html.unescape(paper or "")
    title = letters(paper.split("[")[0].split("(")[0]).removeprefix("the")
    place = re.search(r"\(\[?([^,\[\])]+)", paper)
    found = [rf"(?:{spelled('the')}[\W\d_]*)?{spelled(title)}"] if title else []
    if place and letters(place[1]):
        found.append(spelled(letters(place[1])))
    return [re.compile(rf"(?<![a-z]){name}(?![a-z])", re.IGNORECASE) for name in found]


def masthead(line, paper_names):
    """A line that is only the paper's names, dates, issue words and numbers, or nothing."""
    for pattern in (*paper_names, DATE_WORDS, ISSUE_WORDS, NUMERALS):
        line = pattern.sub(" ", line)
    return len(letters(line)) <= 2


def display_headline(headline, paper):
    paper_names = names(paper)
    return "\n".join(
        line.strip()
        for line in (headline or "").splitlines()
        if not masthead(line, paper_names)
    )

