"""How many candidates whose scan has no batch path can still show a clipping (Phase 2A): a
seeded 100 of them, each looked up on loc.gov the way the crops are (decision 18). It writes
eval/results/phase2a/clipping-probe.json, at one request a second.

    uv run python scripts/clipping_probe.py
"""

import json
from pathlib import Path

import zstandard
from eval_a import uniform

from paperghosts.ingest.crops import BATCH_PATH, page_service
from paperghosts.stats import wilson

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "eval" / "results" / "phase2a" / "clipping-probe.json"
SEED, SIZE = "clipping probe", 100


def probe(row):
    try:
        return {"service": page_service(row["member"], row["scan"]), "error": None}
    except LookupError as exc:  # loc.gov has no item, or the item names no IIIF service
        return {"service": None, "error": str(exc)}


def main():
    report = json.loads((ROOT / "eval" / "results" / "eval_a.json").read_text())
    counts = {y["year"]: y["no_batch_path"] for y in report["by_year"]}
    wanted = {}
    for year, index in uniform(counts, SIZE, SEED):
        wanted.setdefault(year, set()).add(index)
    probes = []
    for year, indexes in sorted(wanted.items()):
        path = ROOT / "data" / "candidates" / f"{year}.jsonl.zst"
        with zstandard.open(path, "rt") as rows:
            seen = 0
            for row in map(json.loads, rows):
                if BATCH_PATH.search((row.get("scan") or {}).get("raw_data_loc") or ""):
                    continue
                if seen in indexes:
                    probes.append(
                        {"year": year, "article_id": row["article_id"], **probe(row)}
                    )
                seen += 1
    OUT.write_text(json.dumps(probes, indent=1) + "\n")
    lost = sum(p["service"] is None for p in probes)
    low, high = wilson(lost, len(probes))
    print(
        f"no clipping for {lost} of {len(probes)} ({lost / len(probes):.0%}, 95% interval {low:.1%}-{high:.1%})"
    )


if __name__ == "__main__":
    main()

