        "gold": len(gold),
        "dev": len(dev),
        "out_of_pool": len(out),
        "pool": len(found["ids"]) - len(out),
        "gold_between_150_and_300": 150 <= len(gold) <= 300,
        "not_in_the_frame": sorted((gold | dev) - set(group_of)),
        "crossing_groups": crossings(found, gold, dev, held, out),
