            if aid in named or group_of.get(aid) in example_groups
        ),
        "hash_matches": hashed,
        "rule": {"leak": LEAK, "fewest": FEWEST},
    }
    result["passed"] = (
        result["gold_between_150_and_300"]
        and hashed
        and not any(
            result[k]
            for k in (
                "not_in_the_frame",
                "crossing_groups",
                "pool_reprints",
                "gold_reprinting_dev",
